mapper.select:
select a.metric_name, a.unit, a.frequency, ifnull(metric_value,ifnull(metric_value_adjusted, -100)) vv, b.* from risk_metric a, risk_metric_value b
b.risk_metric_id = a.id and a.metric_name like concat('%',#{conditions.metricName},'%') and b.metric_code like concat('%',#{conditions.metricCode},'%') and b.need_report = #{conditions.needReport} and b.data_time=#{conditions.dataTime}
order by vv asc
